-- CATEGORIZAÇÃO AUTOMÁTICA DE PRODUTOS NOVOS (Compras Rápidas) — pode rodar de novo sem problema.
-- Quando um produto entra SEM categoria (cadastro, importação da Shopee, qualquer rotina), o gatilho procura o nome
-- (e, se precisar, a descrição) nas regras abaixo e aplica a de maior prioridade. Se nenhuma casar, vai para "A classificar"
-- (categoria oculta, só aparece no painel). Produto que já vem com categoria não é mexido.
-- Padrões: expressão regular sobre o nome em minúsculas e sem acento. \y = começo/fim de palavra.
-- Para mudar: edite as linhas de cr_category_rules (painel do Supabase › Table editor) ou rode este arquivo de novo.
-- Para remover tudo: drop trigger cr_products_categoria_auto on cr_products; drop function cr_products_categoria_auto(); drop function cr_categoria_auto(text); drop table cr_category_rules;

create table if not exists cr_category_rules (
  id bigint generated always as identity primary key,
  category_id uuid not null references cr_categories(id) on delete cascade,
  pattern text not null,
  priority int not null default 50,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
alter table cr_category_rules enable row level security;
drop policy if exists cr_admin_all on cr_category_rules;
create policy cr_admin_all on cr_category_rules for all using (cr_is_admin()) with check (cr_is_admin());
revoke all on cr_category_rules from anon;

-- categoria oculta para o que nenhuma regra reconhecer
insert into cr_categories(name,slug,active,sort) values ('A classificar','a-classificar',false,999) on conflict (slug) do nothing;

-- texto normalizado (minúsculas, sem acento)
create or replace function cr_norm_texto(t text) returns text language sql immutable set search_path=public as $$
  select translate(lower(coalesce(t,'')),'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑáàâãäéèêëíìîïóòôõöúùûüçñ','aaaaaeeeeiiiiooooouuuucnaaaaaeeeeiiiiooooouuuucn') $$;

-- categoria sugerida pelas regras (null = nenhuma casou)
create or replace function cr_categoria_auto(t text) returns uuid language sql stable security definer set search_path=public as $$
  select r.category_id from cr_category_rules r join cr_categories c on c.id=r.category_id
   where r.active and cr_norm_texto(t) ~ r.pattern order by r.priority desc, r.id limit 1 $$;

create or replace function cr_products_categoria_auto() returns trigger language plpgsql security definer set search_path=public as $$
begin
  if new.category_id is null then
    begin
      new.category_id := coalesce(cr_categoria_auto(new.name), cr_categoria_auto(left(new.description, 600)),
                                  (select id from cr_categories where slug='a-classificar'));
    exception when others then   -- uma regra com erro nunca impede o cadastro do produto
      new.category_id := (select id from cr_categories where slug='a-classificar');
    end;
  end if;
  return new;
end $$;
drop trigger if exists cr_products_categoria_auto on cr_products;
create trigger cr_products_categoria_auto before insert on cr_products for each row execute function cr_products_categoria_auto();

-- regras (refeitas do zero a cada execução)
delete from cr_category_rules;
